const int N=100;long long sum[N<<2],lazy[N<<2];
void pushdown(int rt,int l,int r){if(lazy[rt]){int mid=(l+r)>>1;lazy[rt<<1]+=lazy[rt];sum[rt<<1]+=lazy[rt]*(mid-l+1);
lazy[rt<<1|1]+=lazy[rt];sum[rt<<1|1]+=lazy[rt]*(r-mid);lazy[rt]=0;}}
void update(int L,int R,long long v,int l,int r,int rt){if(L<=l&&r<=R){lazy[rt]+=v;sum[rt]+=v*(r-l+1);return;}pushdown(rt,l,r);
int mid=(l+r)>>1;if(L<=mid)update(L,R,v,l,mid,rt<<1);if(R>mid)update(L,R,v,mid+1,r,rt<<1|1);sum[rt]=sum[rt<<1]+sum[rt<<1|1];}
