bool millerRabin(long long n,int k=10){if(n<2)return false;if(n<=3)return true;long long d=n-1;int s=0;while(d%2==0){d/=2;s++;}
for(int i=0;i<k;i++){long long a=2+rand()%(n-3);long long x=qpow(a,d,n);if(x==1||x==n-1)continue;
bool flag=false;for(int r=0;r<s;r++){x=x*x%n;if(x==n-1){flag=true;break;}}if(!flag)return false;}return true;}
int main(){cout<<(millerRabin(1000000007)?"素数":"合数")<<endl;return 0;}

