long long minMax = 1e18;

long long dfs(int u, int fa) {
    sz[u] = w[u];
    long long maxSub = 0;
    for (int v : adj[u]) {
        if (v == fa) continue;
        long long sub = dfs(v, u);
        sz[u] += sub;
        maxSub = max(maxSub, sub);
    }
    maxSub = max(maxSub, total - sz[u]);
    if (maxSub < minMax) {
        minMax = maxSub;
        centroid = u;
    }
    return sz[u];
}

